// Change this to cellular2x2 for a 2x speedup,
// at the cost of some AA ghosting artifacts.

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = 2.0*((fragCoord-0.5*iResolution.xy)/min(iResolution.x, iResolution.y));

    vec2 P1;
    float ID1;
    vec2 F = cellular3x3(uv*8.0, 0.7, P1, ID1);
    float flakes = aastep(0.05, F.y-F.x);

    // A variable amount of peeled-off flakes (0.05 means 5%)
    float missing = step(0.05, ID1/288.0); // ID1 is mod-289
    flakes = min(flakes, missing);

    vec3 bgcolor = vec3(0.5-0.2*abs(ssnoise(vec2(30.0,5.0)*uv)));
    vec3 fgcolor = vec3(1.0, 0.5, 0.0);
    vec3 color = mix(bgcolor, fgcolor, flakes);

    float bump = F.x*F.x;
    float bumpamount = 0.03 * flakes; // No bump in gaps
    // The gradient of F.x*F.x has length 2.0*F.x and points
    // in the direction away from P1. That's simply -2.0*P1.
    vec2 g2 = -2.0*P1; 
    g2 *= 8.0; // Scale with inner derivative (p is 8.0*uv)
    vec3 g = vec3(g2, 0.0);

    vec3 N = vec3(0.0,0.0,1.0); // Simple demo, all in the xy plane

    // Perturb normal
    vec3 N_ = g - dot(g, N) * N; // N_ orthogonal to N
    vec3 bumpedN = N - bump * bumpamount * N_;
    bumpedN = normalize(bumpedN);

    // Roll our own lighting model ("For clarity". Meh.)
    vec3 L;
    L.xy = 2.0*(iMouse.xy-0.5*iResolution.xy)/min(iResolution.x, iResolution.y);
    if (all(equal(iMouse.xy, vec2(0.0)))) L.xy = vec2(0.5);
    L.xy -= uv; // Local illumination (point light, not directional)
    L.z = 2.0;
    L = normalize(L);
    vec3 specularcolor = vec3(flakes); // white flakes, black cracks and gaps
    float lightA = 0.2;  // Ambient light
    float phongD = max(0.0, dot(L, bumpedN));
    float lightD = mix(phongD, 1.0, lightA);
    float lightS = max(0.0, -normalize(
        reflect(L, bumpedN)).z); // Global viewer in -z direction
    lightS = pow(lightS, 16.0);

    vec3 col = lightD * color + 0.7*lightS * specularcolor;

    fragColor = vec4(col, 1.0);

}

