float aastep(float a, float x) {
    float fw = 0.5*fwidth(x-a);
    return smoothstep(-fw, fw, x-a);
}

float aastep(float a, float x, float d) {
    float fw = 0.5*fwidth(d);
    return smoothstep(-fw, fw, x-a);
}

float permute289(float x) {
  return mod((34.0 * x + 10.0) * x, 289.0);
}

// Classic 3x3 search window for better results with jitter>0.5
vec2 cellular3x3(vec2 P, float jitter, out vec2 P1, out float ID1) {
    jitter = clamp(jitter,-1.0,1.0); // Negative jitter makes perfect sense
    vec2 P0 = floor(P);
	vec2 Pi = mod(P0, 289.0);
	vec2 Pf = P0-P + 0.5; // Vector from P to closest unjittered grid point P0
	float px, pxy, d, d1, d2, ox, oy, dx, dy;
	d1 = d2 = 8.0; // Init to distances larger than any actual outcome
	for(float ix = -1.0; ix <=1.0; ix++) {
		px = permute289(Pi.x + ix);
		for(float iy = -1.0; iy <= 1.0; iy++) {
			pxy = permute289(px + Pi.y + iy);
            float psi = pxy*0.07482; // Scale the hash (and jumble it some more)
            // Generate a displacement vector of maximum length
            ox = cos(psi); // sin and cos are usually fast these days
            oy = sin(psi);
            float sqc = jitter * 0.5 / max(abs(ox), abs(oy));
            ox = ox * sqc; // "Square the circle"
			oy = oy * sqc;
			dx = Pf.x + ix + ox;
			dy = Pf.y + iy + oy;
			d = dx*dx + dy*dy; // Distance from P to Pn, squared
            // d could replace either d1 or d2, handle both cases
			d2 = (d <= d1 ? d1 : (d<= d2 ? d : d2));
			P1 = (d <= d1 ? vec2(dx,dy) : P1);
			ID1 = (d <= d1 ? pxy : ID1);
			d1 = (d <= d1 ? d : d1);
		}
	}
	return(sqrt(vec2(d1, d2)));
}

//
// simple simplex noise (c) Stefan Gustavson,
// ver. 2024-11-12, published under CC-BY-SA 4.0
// https://creativecommons.org/licenses/by-sa/4.0/
//
float ssnoise(vec2 p)
{
    // Staggered grid, points at integer y and integer/half x
    // (Yields a slightly non-uniform triangular/hex grid.)
    vec2 uv = vec2(p.x+p.y*0.5, p.y + 0.001); // Transform to skewed space
    vec2 i0 = floor(uv); // Which grid rhombus are we in?
    vec2 f0 = fract(uv); // And which of the two triangles?
    vec2 o1 = (f0.y<f0.x) ? vec2(1.0,0.0) : vec2(0.0,1.0); // offset to 2nd corner
    vec2 i1 = i0 + o1, i2 = i0 + 1.0; // Grid coordinates, used for hash
    vec2 p0 = vec2(i0.x - i0.y*0.5, i0.y); // Transform back to p space
    vec2 p1 = vec2(p0.x + o1.x - o1.y*0.5, p0.y + o1.y);
    vec2 p2 = vec2(p0.x + 0.5, p0.y + 1.0);
    vec2 v0 = p - p0, v1 = p - p1, v2 = p - p2; // Vectors from corners to p

    // Compute a simple hash for each of the three corners using
    // permutation polynomials (predictable, and floating-point only)
    vec3 iu = vec3(i0.x, i1.x, i2.x); // Hash coords
    vec3 iv = vec3(i0.y, i1.y, i2.y);
    vec3 hash = mod(iu, 289.0); // Mod to avoid truncations below
    hash = mod((hash*51.0 + 2.0)*hash + iv, 289.0); // These are not great,
    hash = mod((hash*34.0 + 10.0)*hash, 289.0);     // but "good enough"
    vec3 psi = hash*0.07482; // Scale the hash (and jumble it some more)

    // Generate three gradients
    vec3 gx = cos(psi); // sin and cos are usually fast these days
    vec3 gy = sin(psi);
    vec2 g0 = vec2(gx.x, gy.x);
    vec2 g1 = vec2(gx.y, gy.y);
    vec2 g2 = vec2(gx.z, gy.z);

    // Compute the kernels of influence from each corner
    // The radial decay part
    vec3 w = 0.8 - vec3(dot(v0, v0), dot(v1, v1), dot(v2, v2));
    w = max(w, 0.0); // Cut off the negative part
    vec3 w2 = w*w;
    vec3 w4 = w2*w2; // This is our radial weight
    // The extrapolated linear ramp part
    vec3 gdotv = vec3(dot(g0, v0), dot(g1, v1), dot(g2, v2));
    // Compute and sum up the three contributions in one go
    float n = dot(w4, gdotv);

    // Scale the noise value to span the range [1,1]
    return 10.9*n;
}
